# Shift from 'delete everywhere on event' to 'short-lived revocable leases' at egress boundaries
def egress_to_destination(profile_id, purpose, destination_adapter):
    # If downstream can't prove deletion, data must naturally expire rather than be cleaned up
    lease_token = mint_signed_lease(profile_id, purpose, ttl=destination_adapter.max_safe_window)
    return destination_adapter.sync(project_features(profile_id, purpose), token=lease_token)

def process_opt_out_signal(identity_signal):
    # GPC-to-CRM identity linkage is probabilistic; we must log an explicit graph-severing event
    resolved_nodes = identity_graph.sever_and_isolate(identity_signal)
    append_immutable_tombstone(resolved_nodes)
    # Revoke keys immediately; downstream syncs fail without valid lease signature
    revoke_active_leases(resolved_nodes)

def audit_downstream_state(destination_adapter, tombstone_ledger):
    # Don't trust partner attestations; query synthetic canary identifiers injected during sync
    leaked_canaries = destination_adapter.scan_for_active_records(tombstone_ledger.canary_keys)
    if leaked_canaries: raise LineageViolationAlert(leaked_canaries)

def manage_model_lineage(feature_store, model_registry):
    # Exact ML unlearning is mathematically impractical; track data-to-weight lineage and force retrain thresholds
    taint_ratio = feature_store.calculate_tombstoned_feature_weight(model_registry.active_model)
    if taint_ratio > RETRAIN_TOLERANCE: model_registry.quarantine_and_retrain()
